package com.refind.dao.impl;
import com.refind.dao.ModerationDAO; import com.refind.database.DatabaseConnection; import com.refind.exception.DatabaseException; import com.refind.model.Moderation; import com.refind.model.enums.ModerationDecision; import java.sql.*; import java.util.*;
public class JdbcModerationDAO implements ModerationDAO {
 public Moderation save(Moderation x){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO moderation(claim_id,moderator_id,decision,comment) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,x.getClaim().getId());p.setLong(2,x.getModerator().getId());p.setString(3,x.getDecision().name());p.setString(4,x.getComment());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())x.setId(r.getLong(1));}return x;}catch(SQLException e){throw new DatabaseException("Failed to save moderation decision.",e);}}
 public Optional<Moderation> findById(Long id){return one("SELECT * FROM moderation WHERE id=?",id);} public Optional<Moderation> findByClaim(Long id){return one("SELECT * FROM moderation WHERE claim_id=?",id);} private Optional<Moderation> one(String s,Object v){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setObject(1,v);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();Moderation m=new Moderation();m.setId(r.getLong("id"));var c1=new com.refind.model.Claim();c1.setId(r.getLong("claim_id"));m.setClaim(c1);var u=new com.refind.model.User();u.setId(r.getLong("moderator_id"));m.setModerator(u);m.setDecision(ModerationDecision.valueOf(r.getString("decision")));m.setComment(r.getString("comment"));m.setDecidedAt(r.getTimestamp("decided_at").toLocalDateTime());return Optional.of(m);}}catch(SQLException e){throw new DatabaseException("Failed to query moderation decision.",e);}}
 public List<Moderation> findAll(){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM moderation ORDER BY decided_at DESC");ResultSet r=p.executeQuery()){List<Moderation>a=new ArrayList<>();while(r.next()){Moderation m=new Moderation();m.setId(r.getLong("id"));var cl=new com.refind.model.Claim();cl.setId(r.getLong("claim_id"));m.setClaim(cl);var u=new com.refind.model.User();u.setId(r.getLong("moderator_id"));m.setModerator(u);m.setDecision(ModerationDecision.valueOf(r.getString("decision")));m.setComment(r.getString("comment"));m.setDecidedAt(r.getTimestamp("decided_at").toLocalDateTime());a.add(m);}return a;}catch(SQLException e){throw new DatabaseException("Failed to list moderation decisions.",e);}}
}
